```java
package com.example.bookstore;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.stereotype.Service;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RestController;

@SpringBootApplication  // includes @ComponentScan
public class BookstoreApplication {
    public static void main(String[] args) {
        SpringApplication.run(BookstoreApplication.class, args);
    }
}

@Service  // a component-scan candidate
class BookService {
    String featuredTitle() {
        return "Effective Java";
    }
}

@RestController  // @RestController is built on @Controller
class BookController {
    private final BookService books;

    BookController(BookService books) {
        this.books = books;
    }

    @GetMapping("/books/featured")
    String featured() {
        return books.featuredTitle();
    }
}
```

With `spring-boot-starter-web` on the Boot 3.3.1 classpath, this single-file example starts successfully and `GET /books/featured` returns `Effective Java`.

`SharedComponents.java` marks the extra package without coupling the application to one of its real services.

```java
package com.example.shared;

public interface SharedComponents {
}
```

`BookstoreApplication.java` names both roots.

```java
package com.example.bookstore;

import com.example.shared.SharedComponents;
import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;

@SpringBootApplication(scanBasePackageClasses = {
    BookstoreApplication.class,
    SharedComponents.class
})
public class BookstoreApplication {
    public static void main(String[] args) {
        SpringApplication.run(BookstoreApplication.class, args);
    }
}
```

The string form is valid too: `@SpringBootApplication(scanBasePackages = {"com.example.bookstore", "com.example.shared"})`. The class form is easier to keep correct during refactoring.

```java
package com.example.orders;

import java.time.Clock;
import java.time.Instant;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.stereotype.Service;

@Configuration
class TimeConfiguration {
    @Bean
    Clock orderClock() {
        return Clock.systemUTC();
    }
}

@Service
class ReceiptService {
    private final Clock clock;

    ReceiptService(Clock clock) {
        this.clock = clock;
    }

    Instant issuedAt() {
        return clock.instant();
    }
}
```

`TimeConfiguration` is itself discovered as a configuration component. Its `@Bean` method registers the JDK `Clock`; component scanning registers `ReceiptService`; constructor injection connects them.

```java
package com.example.reports;

import java.util.UUID;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.beans.factory.config.ConfigurableBeanFactory;
import org.springframework.context.annotation.Scope;
import org.springframework.stereotype.Component;
import org.springframework.stereotype.Service;
import org.springframework.web.context.annotation.RequestScope;

@Component
@Scope(ConfigurableBeanFactory.SCOPE_PROTOTYPE)
class ReportDraft {
    private final UUID id = UUID.randomUUID();

    UUID id() {
        return id;
    }
}

@Service  // singleton by default
class ReportService {
    private final ObjectProvider<ReportDraft> drafts;

    ReportService(ObjectProvider<ReportDraft> drafts) {
        this.drafts = drafts;
    }

    ReportDraft startReport() {
        return drafts.getObject(); // fresh prototype per call
    }
}

@Component
@RequestScope
class RequestContext {
    private final UUID correlationId = UUID.randomUUID();

    UUID correlationId() {
        return correlationId;
    }
}
```

Calling `startReport()` twice asks the container twice and returns two draft IDs. Injecting `ReportDraft` directly into the singleton would resolve only one draft when `ReportService` is created.

```java
package com.example.checkout;

import org.springframework.beans.factory.annotation.Qualifier;
import org.springframework.context.annotation.Primary;
import org.springframework.stereotype.Component;
import org.springframework.stereotype.Service;

interface PaymentGateway {
    String mode();
}

@Component
@Primary
class LivePaymentGateway implements PaymentGateway {
    public String mode() { return "live"; }
}

@Component
@Qualifier("sandbox")
class SandboxPaymentGateway implements PaymentGateway {
    public String mode() { return "sandbox"; }
}

@Service
class CheckoutService {
    private final PaymentGateway normal;
    private final PaymentGateway sandbox;

    CheckoutService(
        PaymentGateway normal,
        @Qualifier("sandbox") PaymentGateway sandbox
    ) {
        this.normal = normal;     // @Primary candidate
        this.sandbox = sandbox;   // qualifier match
    }
}
```

The constructor is the class's only constructor, so it does not need `@Autowired`. Removing both `@Primary` and the sandbox qualifier leaves two equally suitable single-value candidates and makes context creation fail.
